:root {
  --bg: #1e1e2e;
  --card: #2a2a3c;
  --text: #e0e0e0;
  --accent: #f5a623;
  --hunger: #e85d5d;
  --happiness: #5de8a0;
  --energy: #5d9de8;
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px;
  width: min(100%, 420px);
  text-align: center;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  color: var(--accent);
  letter-spacing: 1px;
}

/* Pet */
.pet-stage {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.pet {
  position: relative;
  width: 120px;
  height: 120px;
  image-rendering: pixelated;
}

.pet .ear {
  position: absolute;
  width: 24px;
  height: 24px;
  background: var(--accent);
  top: 0;
  border-radius: 4px;
}
.pet .ear.left { left: 12px; }
.pet .ear.right { right: 12px; }

.pet .face {
  position: absolute;
  top: 20px;
  left: 20px;
  width: 80px;
  height: 60px;
  background: var(--accent);
  border-radius: 8px;
}

.pet .eye {
  position: absolute;
  width: 12px;
  height: 12px;
  background: #1e1e2e;
  border-radius: 2px;
  top: 16px;
}
.pet .eye.left { left: 12px; }
.pet .eye.right { right: 12px; }

.pet .mouth {
  position: absolute;
  width: 24px;
  height: 8px;
  background: #1e1e2e;
  border-radius: 0 0 12px 12px;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
}

.pet .body {
  position: absolute;
  bottom: 0;
  left: 30px;
  width: 60px;
  height: 40px;
  background: var(--accent);
  border-radius: 8px 8px 4px 4px;
}

.pet .tail {
  position: absolute;
  bottom: 10px;
  right: 10px;
  width: 16px;
  height: 16px;
  background: var(--accent);
  border-radius: 50%;
}

/* Mood */
.mood {
  margin: 0 0 20px;
  font-size: 1.1rem;
  font-weight: 600;
  min-height: 1.5em;
  color: var(--accent);
}

/* Stats */
.stats {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.stat {
  display: flex;
  align-items: center;
  gap: 12px;
}

.stat-label {
  width: 80px;
  text-align: left;
  font-size: 0.9rem;
  font-weight: 600;
}

.bar {
  flex: 1;
  height: 20px;
  background: #1e1e2e;
  border-radius: 10px;
  overflow: hidden;
}

.fill {
  height: 100%;
  width: 50%;
  border-radius: 10px;
  transition: width 0.3s ease;
}
.fill.hunger { background: var(--hunger); }
.fill.happiness { background: var(--happiness); }
.fill.energy { background: var(--energy); }

/* Controls */
.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  flex: 1 1 0;
  min-width: 90px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--bg);
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover { background: #ffb84d; }
button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}
button:active { transform: scale(0.96); }

@media (max-width: 400px) {
  .card { padding: 16px; }
  .stat-label { width: 70px; font-size: 0.85rem; }
  button { min-width: 70px; padding: 10px 12px; font-size: 0.95rem; }
}

(function () {
  'use strict';

  const state = {
    hunger: 50,
    happiness: 50,
    energy: 50
  };

  const DECAY_INTERVAL = 5000;
  const DECAY_AMOUNT = 2;

  const els = {
    mood: document.getElementById('mood'),
    hungerFill: document.getElementById('hunger-fill'),
    happinessFill: document.getElementById('happiness-fill'),
    energyFill: document.getElementById('energy-fill'),
    hungerBar: document.getElementById('hunger-bar'),
    happinessBar: document.getElementById('happiness-bar'),
    energyBar: document.getElementById('energy-bar'),
    feed: document.getElementById('feed'),
    play: document.getElementById('play'),
    sleep: document.getElementById('sleep')
  };

  function clamp(value) {
    return Math.max(0, Math.min(100, value));
  }

  function updateMood() {
    const avg = (state.hunger + state.happiness + state.energy) / 3;
    let text;
    if (state.hunger < 20) text = 'Your pet is starving!';
    else if (state.energy < 20) text = 'Your pet is exhausted...';
    else if (state.happiness < 20) text = 'Your pet is sad.';
    else if (avg > 80) text = 'Your pet is overjoyed!';
    else if (avg > 60) text = 'Your pet is happy!';
    else if (avg > 40) text = 'Your pet is okay.';
    else text = 'Your pet needs attention.';
    els.mood.textContent = text;
  }

  function render() {
    els.hungerFill.style.width = state.hunger + '%';
    els.happinessFill.style.width = state.happiness + '%';
    els.energyFill.style.width = state.energy + '%';

    els.hungerBar.setAttribute('aria-valuenow', String(Math.round(state.hunger)));
    els.happinessBar.setAttribute('aria-valuenow', String(Math.round(state.happiness)));
    els.energyBar.setAttribute('aria-valuenow', String(Math.round(state.energy)));

    updateMood();
  }

  function feed() {
    state.hunger = clamp(state.hunger + 15);
    state.happiness = clamp(state.happiness + 5);
    state.energy = clamp(state.energy - 5);
    render();
  }

  function play() {
    state.happiness = clamp(state.happiness + 15);
    state.energy = clamp(state.energy - 10);
    state.hunger = clamp(state.hunger - 5);
    render();
  }

  function sleep() {
    state.energy = clamp(state.energy + 20);
    state.hunger = clamp(state.hunger - 5);
    state.happiness = clamp(state.happiness - 5);
    render();
  }

  els.feed.addEventListener('click', feed);
  els.play.addEventListener('click', play);
  els.sleep.addEventListener('click', sleep);

  setInterval(function () {
    state.hunger = clamp(state.hunger - DECAY_AMOUNT);
    state.happiness = clamp(state.happiness - DECAY_AMOUNT);
    state.energy = clamp(state.energy - DECAY_AMOUNT);
    render();
  }, DECAY_INTERVAL);

  render();
})();
